window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[40]={"id":"040","numero":40,"titre":"Algies pelviennes chez la femme","objectifs":[{"id":"40-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la douleur pelvienne aiguë (DPA) et chronique (DPC)","contenu":"<p>Les <span class=\"kw-def\">algies pelviennes</span> regroupent l’ensemble des <strong>symptômes douloureux, spontanés ou provoqués</strong>, de la région <strong><span class=\"kw-clinique\">hypogastre</span></strong> et/ou des <strong><span class=\"kw-clinique\">fosses iliaques</span></strong> droite et gauche. Elles sont l’un des motifs de consultation gynécologique les plus fréquents.</p>\n\n      <table >\n        <thead>\n          <tr><th>Forme</th><th><span class=\"kw-clinique\">Évolution</span></th><th>Caractéristiques sémiologiques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Douleur pelvienne aiguë (DPA)</strong></td>\n            <td><span class=\"kw-chiffre\">&lt; 1 mois</span> · début récent · <span class=\"kw-clinique\">évolution</span> rapide</td>\n            <td>Douleur <strong>subite</strong>, type <em>coup de poignard</em>, torsion, colique, <span class=\"kw-clinique\">irradiation</span> possible</td>\n          </tr>\n          <tr>\n            <td><strong>Douleur pelvienne chronique (DPC)</strong></td>\n            <td><span class=\"kw-chiffre\">&gt; 6 mois</span> · permanente ou intermittente · <strong>cyclique ou non</strong></td>\n            <td><span class=\"kw-clinique\">Pesanteur</span>, tiraillement, picotement · ± rythmée par le cycle menstruel</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p>3 voies d’innervation principales du pelvis structurent la <span class=\"kw-def\">topographie</span> de la douleur :</p>\n      <ul>\n        <li><strong>Plexus pelvien</strong> (vagin, col, isthme utérin, ligaments utéro-sacrés, cul-de-sac recto-utérin, bas uretères, trigone vésical, recto-sigmoïde) → douleur <strong>sacrée ou périnéale</strong></li>\n        <li><strong>Plexus hypogastrique</strong> (corps utérin, 1/3 proximal des trompes, ligament large, calotte vésicale) → douleur <strong>hypogastrique</strong></li>\n        <li><strong>Plexus aortique</strong> (ovaires, portion distale des trompes, uretères rétro-ligamentaires) → douleur <strong><span class=\"kw-clinique\">fosses iliaques</span>, flancs et fosses lombaires</strong></li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Une douleur pelvienne aiguë <em>n’a pas d’étiologie retrouvée dans <span class=\"kw-chiffre\">25–50 %</span> des cas</em>. Pour les douleurs <strong>chroniques</strong>, les causes par ordre décroissant sont : <strong>digestives &gt; urinaires &gt; gynécologiques</strong>.\n      </div>","frequence":0},{"id":"40-2","rang":"A","rubrique":"Étiologies","titre":"Connaître les étiologies des DPA","contenu":"<p>Les étiologies des <span class=\"kw-def\">douleurs pelviennes aiguës (DPA)</span> sont classées en <strong><span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>6</span> g</span>rands cadres</strong> à mémoriser de façon systématique pour orienter l’interrogatoire et le bilan.</p>\n\n      <table >\n        <thead>\n          <tr><th>Cadre</th><th>Étiologies</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Post-<span class=\"kw-ci\">grossesse</span></strong></td>\n            <td>\n              <span class=\"kw-alerte\">GEU</span> · <span class=\"kw-etio\">fausse couche spontanée</span> · rétention post-FC · <span class=\"kw-etio\">endométrite du post-partum</span> ou post-abortum · complication du corps jaune gestationnel (<span class=\"kw-etio\">hémorragique</span>, kyste et ses complications)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Infectieuses</strong></td>\n            <td>\n              <span class=\"kw-clinique\">IGH</span> (<span class=\"kw-etio\">salpingite</span>, endométrite, <span class=\"kw-etio\">pelvipéritonite</span>, <span class=\"kw-clinique\">abcès</span> tubo-ovarien) · <span class=\"kw-alerte\">appendicite aiguë</span> · <span class=\"kw-etio\">PNA</span> · IU basse\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Annexielles</strong></td>\n            <td>\n              <span class=\"kw-alerte\">Torsion d’annexe</span> · complications de kyste ovarien (hémorragie intra-kystique, <span class=\"kw-alerte\">rupture</span>, torsion) · dysovulation\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Sur présence d’un fibrome</strong></td>\n            <td>\n              <span class=\"kw-etio\">Nécrobiose aiguë</span> · torsion d’un myome sous-séreux pédiculé · accouchement d’un myome sous-muqueux par le col utérin\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Urologique</strong></td>\n            <td>\n              <span class=\"kw-etio\">Colique néphrétique</span> · <span class=\"kw-etio\">PNA</span> · IU basse\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Rares</strong></td>\n            <td>\n              Sacro-iléite <span class=\"kw-etio\">bactérienne</span> · ostéite · anévrisme de l’artère iliaque · infection d’un kyste de l’ouraque\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span class=\"kw-ci\">Grossesse</span> normale · 25 — GEU · 41 — Endométriose · 158 — <span class=\"kw-def\">Sepsis</span> · 354 — Syndrome occlusif (DD appendicite)</em></p>","frequence":0},{"id":"40-3","rang":"B","rubrique":"Physiopathologie","titre":"Connaître la physiopathologie des DPA et des DPC","contenu":"<p>La <span class=\"kw-def\">physiopathologie</span> diffère entre douleur aiguë (mécanisme lésionnel direct) et douleur chronique (mécanismes multiples intriqués).</p>\n\n      <h4>Douleur pelvienne aiguë — voies de la douleur</h4>\n      <p>L’interprétation sémiologique est <strong>difficile</strong> : proximité des organes pelviens + innervation commune. Trois plexus efférents structurent la topographie :</p>\n      <table >\n        <thead>\n          <tr><th>Plexus</th><th>Organes</th><th>Topographie de la douleur</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Hypogastrique</strong></td>\n            <td>Corps utérin, 1/3 proximal des trompes, ligament large, calotte vésicale</td>\n            <td>Hypogastrique</td>\n          </tr>\n          <tr>\n            <td><strong>Aortique</strong></td>\n            <td>Ovaires, portion distale des trompes, uretères rétro-ligamentaires</td>\n            <td>Flancs, <span class=\"kw-clinique\">fosses iliaques</span>, fosses lombaires</td>\n          </tr>\n          <tr>\n            <td><strong>Pelvien</strong></td>\n            <td>Vagin, col/isthme, ligaments utéro-sacrés, bas uretères, trigone vésical, cul-de-sac de Douglas, recto-sigmoïde</td>\n            <td><strong>Sacrée</strong> et <strong>périnéale</strong></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Douleur pelvienne chronique — hypothèses physiopathologiques</h4>\n      <ul>\n        <li><strong>Hypothèse <span class=\"kw-etio\">ischémique</span></strong> : les <span class=\"kw-bio\">prostaglandines</span> ↗ les contractions utérines → ischémie utérine relative douloureuse</li>\n        <li><strong>Hypothèse spasmodique</strong> : les <span class=\"kw-bio\">prostaglandines</span> ↗ le tonus du sphincter cervico-isthmique, désynchronisé du cycle → retard d’ouverture du col → gêne à l’écoulement menstruel</li>\n        <li><strong>Hypothèse congestive</strong> : stase pelvienne (<span class=\"kw-clinique\">constipation</span>, faiblesse musculaire pelvienne, varices pelviennes)</li>\n        <li><strong>Facteurs hormonaux</strong> : déséquilibre œstroprogestatif en phase lutéale (hyperœstrogénie relative) → congestion ; pics et chutes d’œstrogènes expliquent les douleurs intermenstruelles et prémenstruelles</li>\n        <li><strong>Facteurs psychologiques</strong> : zone pelvi-génitale = site fréquent de somatisation → rôle dans le <strong>maintien</strong> de la douleur chronique</li>\n      </ul>","frequence":0},{"id":"40-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaitre les élements de l’interrogatoire et de l’examen clinique utiles au diagnostic des DPA","contenu":"<p>La <span class=\"kw-def\">démarche diagnostique</span> repose sur un interrogatoire structuré, différent selon que la douleur est aiguë ou chronique, et un examen physique adapté (abdominal + spéculum + <span class=\"kw-alerte\">TV</span>).</p>\n\n      <h4>Interrogatoire</h4>\n\n      <table >\n        <thead>\n          <tr><th>Axe</th><th>Douleur aiguë</th><th>Douleur chronique</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Date d’apparition</strong></td>\n            <td>Récente (<span class=\"kw-chiffre\">&lt; 1 mois</span>), <strong>subite</strong></td>\n            <td>Moins récente, <span class=\"kw-clinique\">évolution</span> <span class=\"kw-chiffre\">&gt; 6 mois</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Évolution</span></strong></td>\n            <td>Rapide</td>\n            <td>Permanente ou intermittente</td>\n          </tr>\n          <tr>\n            <td><strong>Apparition dans le cycle</strong></td>\n            <td>—</td>\n            <td>Prémenstruel, <strong><span class=\"kw-clinique\">dysménorrhée</span></strong>, intermenstruel</td>\n          </tr>\n          <tr>\n            <td><strong>Type</strong></td>\n            <td>Coup de poignard, torsion, colique, <span class=\"kw-clinique\">irradiation</span></td>\n            <td><span class=\"kw-clinique\">Pesanteur</span>, tiraillement, picotement, irradiation</td>\n          </tr>\n          <tr>\n            <td><strong>Signes associés</strong></td>\n            <td>\n              Date des dernières règles<br>\n              <span class=\"kw-clinique\">Syndrome <span class=\"kw-etio\">infectieux</span></span><br>\n              <span class=\"kw-clinique\">Nausées</span>, <span class=\"kw-clinique\">vomissements</span>, SFU<br>\n              Signes de <span class=\"kw-ci\">grossesse</span>, métrorragies, position <span class=\"kw-ttt\">antalgique</span>\n            </td>\n            <td>\n              <span class=\"kw-clinique\">Céphalées</span>, lombalgie, diarrhées, <span class=\"kw-clinique\">constipation</span><br>\n              Métrorragies, <span class=\"kw-clinique\">dyspareunies</span>, infertilité\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Antécédents</strong></td>\n            <td>\n              GOB, chirurgicaux<br>\n              Contraception · conduite à risque (IST)\n            </td>\n            <td>\n              Gynécologiques, obstétricaux, chirurgicaux, CO<br>\n              Retentissement sur la qualité de vie\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Examen clinique</h4>\n\n      <ul>\n        <li><strong>Inspection · palpation abdominale</strong> : recherche de défense, contracture, <span class=\"kw-clinique\">masse</span></li>\n        <li><strong>Spéculum</strong> : <span class=\"kw-clinique\">leucorrhées</span>, métrorragies, aspect du col</li>\n        <li><strong>Toucher vaginal (<span class=\"kw-alerte\">TV</span>)</strong> :\n          <ul>\n            <li>Douleur à la mobilisation utérine (orientation IGH)</li>\n            <li><span class=\"kw-clinique\">Masse</span> latéro-utérine (GEU, kyste compliqué)</li>\n            <li>Sensibilité du cul-de-sac de Douglas (hémopéritoine, IGH)</li>\n            <li><span class=\"kw-ci\">Hypersensibilité</span> de la paroi vaginale antérieure (<strong>syndrome douloureux vésical</strong>)</li>\n          </ul>\n        </li>\n        <li><strong><span class=\"kw-bio\">BU</span></strong> systématique : <span class=\"kw-bio\">nitrites</span>, <span class=\"kw-bio\">leucocytes</span>, <span class=\"kw-clinique\">hématurie</span></li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Toute femme en âge de procréer avec une douleur pelvienne aiguë doit avoir : <strong>β-hCG plasmatique + <span class=\"kw-bio\">BU</span> + écho pelvienne</strong> en <span class=\"kw-chiffre\">première ligne</span> — c’est la triade qui élimine les 4 urgences.\n      </div>","frequence":0},{"id":"40-5","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les examens complémentaires biologiques","contenu":"<p>Toute femme en âge de procréer avec une <span class=\"kw-def\">douleur pelvienne aiguë</span> bénéficie d’un bilan <span class=\"kw-ttt\">biologique</span> de <strong>1ʳᵉ intention</strong> centré sur l’élimination des urgences.</p>\n\n      <div class=\"callout callout-info\">\n        <strong>Réflexe 1ʳᵉ intention.</strong> <span class=\"kw-bio\">β-hCG</span> + <span class=\"kw-bio\">NFS</span> + <span class=\"kw-bio\">CRP</span> + <span class=\"kw-bio\">BU</span> + <span class=\"kw-bio\">prélèvements vaginaux</span>/endocervicaux (si suspicion d’IGH).\n      </div>\n\n      <table >\n        <thead>\n          <tr><th>Examen</th><th>Intérêt · interprétation</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-bio\">β-hCG</span></strong></td>\n            <td>Indispensable chez toute femme en période d’activité génitale · <strong>si négatif → élimine une GEU</strong></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">NFS</span></strong></td>\n            <td>\n              <strong>Anémie</strong> → hémopéritoine<br>\n              Hyperleucocytose : quasi-constante dans l’appendicite · <strong>fréquemment absente dans l’IGH simple</strong> (si présente → forme compliquée) · fréquente sur nécrobiose · rare sur torsion d’annexe\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">CRP</span></strong></td>\n            <td><span class=\"kw-clinique\">Syndrome <span class=\"kw-etio\">inflammatoire</span></span> → cause infectieuse (IGH, appendicite) · <span class=\"kw-bio\">CRP</span> très élevée + IGH → évoque un <span class=\"kw-alerte\">abcès tubo-ovarien</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">Bandelette urinaire</span></strong></td>\n            <td>Nitrites + <span class=\"kw-bio\">leucocyturie</span> → <strong>infection urinaire</strong> · <span class=\"kw-clinique\">hématurie</span> → colique néphrétique (impose une écho des voies urinaires)</td>\n          </tr>\n          <tr>\n            <td><strong>Bactériologie</strong></td>\n            <td>Prélèvements vaginaux + endocervicaux : <strong>indispensables si suspicion d’IGH</strong> (<span class=\"kw-etio\">gonocoque</span>, <em>C. trachomatis</em>, <em>M. genitalium</em>) · ablation + mise en culture du DIU si IGH</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">Biopsie d’endomètre</span></strong><br><em>(2ᵈᵉ intention)</em></td>\n            <td>Doute <span class=\"kw-ci\">grossesse</span> arrêtée / GEU → présence de <em>villosités choriales</em> élimine la GEU · suspicion d’IGH paucisymptomatique → signes histologiques d’endométrite</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège ⭐.</strong> <em>Aucun examen <span class=\"kw-ttt\">biologique</span> n’affirme le syndrome douloureux vésical chronique</em> : l’<span class=\"kw-bio\">ECBU</span> y est <strong>stérile</strong> (<span class=\"kw-bio\">leucocyturie</span> possible) — le diagnostic est endoscopique (<span class=\"kw-imagerie\">cystoscopie</span>), traité en onglet « Astuces PU ».\n      </div>","frequence":1},{"id":"40-6","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les urgences chirurgicales devant une douleur aiguë pelvienne","contenu":"<p>Devant toute <span class=\"kw-def\">douleur pelvienne aiguë chez une femme</span>, <strong>5 diagnostics</strong> doivent être évoqués systématiquement car ils engagent le <span class=\"kw-alerte\">pronostic vital et/ou fonctionnel</span> :</p>\n\n      <ol>\n        <li><strong>GEU</strong> (<span class=\"kw-ci\">grossesse</span> extra-utérine)</li>\n        <li><strong>Torsion d’annexe</strong></li>\n        <li><strong><span class=\"kw-alerte\">Rupture</span> <span class=\"kw-etio\">hémorragique</span> de kyste</strong> (hémopéritoine)</li>\n        <li><strong>IGH</strong> (infection génitale haute)</li>\n        <li><strong>Appendicite aiguë</strong></li>\n      </ol>\n\n      <table >\n        <thead>\n          <tr><th>Entité</th><th>Interrogatoire — éléments clés</th><th>Examen clinique</th><th>Examens complémentaires</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">GEU</span></strong><br><em>Nidation embryonnaire hors cavité utérine (<span class=\"kw-chiffre\">2 %</span> des grossesses)</em></td>\n            <td>\n              Douleurs pelviennes aiguës + métrorragies <em>« sépia »</em> + retard de règles<br>\n              Signes sympathiques de <span class=\"kw-ci\">grossesse</span> (<span class=\"kw-clinique\">nausées</span>, tension mammaire)<br>\n              FDR : <span class=\"kw-clinique\">ATCD IGH/chirurgie</span>, <span class=\"kw-etio\">tabagisme</span> actif, FIV\n            </td>\n            <td>\n              Défense ± contracture<br>\n              <span class=\"kw-alerte\">TV</span> : douleur provoquée + <span class=\"kw-clinique\">masse</span> latéro-utérine, palpation du cul-de-sac de Douglas douloureuse<br>\n              <span class=\"kw-alerte\">Signes de gravité</span> : <span class=\"kw-alerte\">hémopéritoine</span>, scapulalgie, anomalies HDM\n            </td>\n            <td>\n              β-hCG <span class=\"kw-chiffre\">&gt; 1500 UI/L</span><br>\n              Écho endovaginale : <strong>vacuité utérine</strong>, endomètre épais, présence du corps jaune, épanchement Douglas, hémopéritoine\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">Torsion d’annexe</span></strong><br><em>Ovaire ou ovaire + trompe (rare sur trompe saine)</em></td>\n            <td>\n              Douleur <em>brutale, en coup de poignard</em><br>\n              Troubles digestifs (<span class=\"kw-clinique\">nausées</span>, <span class=\"kw-clinique\">vomissements</span>, arrêt des gaz)<br>\n              ATCD de kyste ovarien connu\n            </td>\n            <td>\n              Défense abdominale ± météorisme<br>\n              <span class=\"kw-alerte\">TV</span> : douleur latéro-utérine unilatérale <strong>très douloureuse au niveau du collet</strong>\n            </td>\n            <td>\n              Écho pelvienne : ovaire augmenté de taille ± kyste associé, <strong>anomalies de vascularisation</strong> (disparition du pédicule ovarien au <span class=\"kw-imagerie\">Doppler</span>)\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">Rupture</span> <span class=\"kw-etio\">hémorragique</span> de kyste</strong><br><em><span class=\"kw-alerte\"><span class=\"kw-def\">Pronostic</span> vital</span> engagé</em></td>\n            <td>\n              Douleurs brutales, intenses ± <span class=\"kw-clinique\">scapulalgie</span><br>\n              Gravité : instabilité HDM<br>\n              ATCD de kyste ovarien\n            </td>\n            <td>\n              Défense abdominale ± contracture<br>\n              <span class=\"kw-alerte\">TV</span> : douleur diffuse, cul-de-sac de Douglas comblé\n            </td>\n            <td>\n              Écho pelvienne : <strong>kyste ovarien + hémopéritoine</strong><br>\n              <span class=\"kw-bio\">NFS</span> : anémie\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">IGH</span></strong><br><em>Salpingite, endométrite, <span class=\"kw-clinique\">abcès</span> tubo-ovarien</em></td>\n            <td>\n              Douleurs modérées d’installation lente (évocatrice si <span class=\"kw-chiffre\">&gt; 4 jours</span>) ± SFU ± <span class=\"kw-clinique\">irradiation</span> lombaire ou hypocondre droit<br>\n              <span class=\"kw-clinique\">Syndrome <span class=\"kw-etio\">infectieux</span></span><br>\n              Ténesme → rechercher <strong><span class=\"kw-clinique\">abcès</span> tubo-ovarien</strong><br>\n              FDR : rapports non protégés, multiples partenaires, gestes récents\n            </td>\n            <td>\n              <span class=\"kw-alerte\">Irritation péritonéale</span> : défense <span class=\"kw-clinique\">hypogastre</span>/hypocondre droit (<strong><span class=\"kw-clinique\">syndrome de Fitz</span>-Hugh-Curtis</strong>)<br>\n              Leucorrhées abondantes, épaisses, jaunâtres ± purulentes<br>\n              Métrorragies<br>\n              <span class=\"kw-alerte\">TV</span> : douloureux ++ à la mobilisation utérine et au cul-de-sac de Douglas, douleur bilatérale à la palpation des annexes\n            </td>\n            <td>\n              <span class=\"kw-bio\">NFS</span> : <span class=\"kw-clinique\">SIB</span><br>\n              Bactériologie : recherche d’IST (<span class=\"kw-etio\">gonocoque</span>, <em>C. trachomatis</em>, <em>M. genitalium</em>)<br>\n              Écho : <span class=\"kw-alerte\"><span class=\"kw-def\">critères de</span> gravité</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">Appendicite aiguë</span></strong><br><em>DD chirurgical majeur, surtout à droite</em></td>\n            <td>\n              Douleur débutant en épigastre/péri-ombilical puis <strong>migrant en FID</strong><br>\n              <span class=\"kw-clinique\">Nausées</span>, <span class=\"kw-clinique\">vomissements</span>, fébricule<br>\n              <span class=\"kw-clinique\">Diarrhée</span> rare\n            </td>\n            <td>\n              <strong>Langue saburrale</strong>, défense FID<br>\n              Signe de <strong>Rovsing</strong> (douleur FID à la palpation de la FIG)<br>\n              Signe de <strong>Blumberg</strong> (douleur à la décompression)<br>\n              <strong>Psoïtis</strong>\n            </td>\n            <td>\n              <span class=\"kw-bio\">NFS</span> : hyperleucocytose quasi-constante · <span class=\"kw-bio\">CRP</span> ↗<br>\n              Écho : <span class=\"kw-clinique\">diamètre</span> appendiculaire <span class=\"kw-chiffre\">&gt; 6 mm</span>, paroi <span class=\"kw-chiffre\">&gt; 3 mm</span>, appendice incompressible, épanchement FID\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> Une <em>douleur pelvienne aiguë chez une femme en âge de procréer = β-hCG en <span class=\"kw-alerte\">urgence</span></em>, quel que soit le contexte contraceptif allégué. Pas de β-hCG = pas de diagnostic.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 25 — GEU · 158 — <span class=\"kw-def\">Sepsis</span> · 354 — Syndrome occlusif (appendicite)</em></p>","frequence":1},{"id":"40-7","rang":"A","rubrique":"Définition","titre":"Savoir distinguer les douleurs chroniques des douleurs aiguës","contenu":"<p>La distinction <span class=\"kw-def\">aiguë / chronique</span> repose avant tout sur la <strong>durée d’<span class=\"kw-clinique\">évolution</span></strong> et conditionne toute la démarche (<span class=\"kw-alerte\">urgence</span> <span class=\"kw-bio\">vs</span> bilan ambulatoire).</p>\n\n      <table >\n        <thead>\n          <tr><th>Critère</th><th>Douleur pelvienne aiguë (DPA)</th><th>Douleur pelvienne chronique (DPC)</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Durée</strong></td>\n            <td><span class=\"kw-chiffre\">&lt; 1 mois</span></td>\n            <td><span class=\"kw-chiffre\">&gt; 6 mois</span></td>\n          </tr>\n          <tr>\n            <td><strong>Installation</strong></td>\n            <td>Subite, récente</td>\n            <td>Progressive, ancienne · <strong>cyclique ou non</strong></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Évolution</span></strong></td>\n            <td>Rapide</td>\n            <td>Permanente ou intermittente</td>\n          </tr>\n          <tr>\n            <td><strong>Type</strong></td>\n            <td>Coup de poignard, torsion, colique</td>\n            <td><span class=\"kw-clinique\">Pesanteur</span>, tiraillement, picotement</td>\n          </tr>\n          <tr>\n            <td><strong>Enjeu</strong></td>\n            <td><span class=\"kw-alerte\">Éliminer une urgence</span> (GEU, torsion, IGH, appendicite)</td>\n            <td>Retentissement sur la qualité de vie · errance diagnostique fréquente</td>\n          </tr>\n          <tr>\n            <td><strong>Causes dominantes</strong></td>\n            <td>Gynéco / obstétricales / chirurgicales aiguës</td>\n            <td>Digestives &gt; urinaires &gt; gynécologiques</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> Une DPC peut se <em>décompenser en aigu</em> (ex. endométriose, torsion sur kyste connu) : un <span class=\"kw-def\">terrain</span> chronique n’élimine jamais une <span class=\"kw-alerte\">urgence</span> surajoutée.\n      </div>","frequence":0},{"id":"40-8","rang":"A","rubrique":"Définition","titre":"Connaître les principales étiologies des DPC","contenu":"<p>Les <span class=\"kw-def\">douleurs pelviennes chroniques (DPC)</span> évoluent depuis plus de <span class=\"kw-chiffre\">6 mois</span>. Elles peuvent être <strong>cycliques</strong> (rythmées par le cycle) ou <strong>non cycliques</strong>.</p>\n\n      <h4>Douleur pelvienne chronique <em>non cyclique</em></h4>\n\n      <table >\n        <thead>\n          <tr><th>Origine</th><th>Étiologies</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Extra-génitale</strong></td>\n            <td>\n              <strong>Digestive</strong> : <span class=\"kw-etio\">colite</span>, <span class=\"kw-etio\">MICI</span>, endométriose digestive, <span class=\"kw-etio\">hémorroïdes</span>, anomalies anorectales<br>\n              <strong>Urinaire</strong> : cystalgie à urines claires (signes urinaires + urines stériles)<br>\n              <strong>Rhumatologique</strong> : pathologies ostéo-articulaires du bassin ou du rachis lombaire (accentuées par certaines positions)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Génitale organique</strong></td>\n            <td>\n              Infections génitales <em>chroniques</em> ou <em>subaiguës</em> (infection vulvo-vaginale, cervicale, endométrite chronique, annexielle subaiguë)<br>\n              <strong><span class=\"kw-etio\">Syndrome de Masters et Allen</span></strong> : trouble de la statique pelvienne par déficit des ligaments utéro-sacrés (souvent post-accouchement traumatique ou macrosome) → <span class=\"kw-clinique\">pesanteur</span> soulagée en décubitus, aggravée à l’orthostatisme, <span class=\"kw-clinique\">dyspareunies profondes</span>, utérus très mobile au <span class=\"kw-alerte\">TV</span><br>\n              <strong><span class=\"kw-etio\">Syndrome de congestion pelvienne</span></strong> : varices pelviennes ou ovariennes, post-<span class=\"kw-ci\">grossesse</span>, aggravation à la station debout ou aux rapports<br>\n              <span class=\"kw-clinique\">Endométriose pelvienne</span> (rétroversion utérine douloureuse par rétraction)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Génitale fonctionnelle</strong></td>\n            <td>\n              Douleurs séquellaires de cicatrice d’épisiotomie, atrophie vulvo-vaginale (hypœstrogénie)<br>\n              Facteurs psychologiques (dépister <span class=\"kw-alerte\">violences</span> sexuelles ou conjugales)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Douleur pelvienne chronique <em>cyclique</em></h4>\n\n      <ul>\n        <li><strong><span class=\"kw-etio\">Syndrome prémenstruel</span></strong></li>\n        <li><strong>Syndrome intermenstruel</strong> : douleur contemporaine de la période ovulatoire, peu intense, quelques jours en milieu de cycle ± métrorragies → examen rassurant, pas d’examens paracliniques, <span class=\"kw-ttt\">antalgiques simples</span> ± <span class=\"kw-ttt\">anti-gonadotrope</span></li>\n        <li><strong><span class=\"kw-etio\">Dysménorrhées</span></strong> : douleurs contemporaines des règles ± troubles digestifs/urinaires/<span class=\"kw-clinique\">céphalées</span> :\n          <ul>\n            <li><em>Organiques</em> (« secondaires ») : <span class=\"kw-clinique\">endométriose</span>, sténoses cervicales (congénitales ou acquises), anomalies utéro-vaginales (synéchies, cancer du col, <span class=\"kw-ttt\">chirurgie</span> cervicale, malformations congénitales)</li>\n            <li><em>Fonctionnelles</em> : <span class=\"kw-def\">prévalence</span> élevée entre <span class=\"kw-chiffre\">20-24 ans</span>, diminution avec l’âge, majoritairement <strong>psychogènes</strong> (diagnostic d’élimination)</li>\n          </ul>\n        </li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 41 — Endométriose · 42 — Aménorrhée · 43 — Hémorragie génitale</em></p>","frequence":0},{"id":"40-9","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les indications des examens d’imagerie devant une algie pelvienne chez la femme","contenu":"<p>La hiérarchisation des examens dépend du contexte (aigu <span class=\"kw-bio\">vs</span> chronique) et de l’orientation clinique. La règle EDN : <strong>β-hCG + <span class=\"kw-bio\">BU</span> + écho pelvienne</strong> pour toute douleur aiguë chez une femme en âge de procréer.</p>\n\n      <table >\n        <thead>\n          <tr><th>Examen</th><th>Indications · résultats à interpréter</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">Échographie pelvienne</span></strong><br><em>(examen-clé de 1ʳᵉ intention)</em></td>\n            <td>\n              <span class=\"kw-imagerie\">À réaliser en urgence</span> si instabilité HDM ou suspicion d’hémopéritoine<br>\n              <strong>Voie abdominale + endovaginale</strong> (sauf vierge → abdominale seule)<br>\n              GEU : <span class=\"kw-radio\">vacuité utérine, masse latéro-utérine, épanchement de Douglas</span><br>\n              Torsion : ovaire augmenté ± kyste, <span class=\"kw-radio\">arrêt des flux au Doppler</span><br>\n              IGH : épaississement de la paroi tubaire, épanchement intra-tubaire, <span class=\"kw-alerte\">abcès tubo-ovarien</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Écho des voies urinaires</strong></td>\n            <td>Indiquée si <span class=\"kw-clinique\">hématurie</span> à la <span class=\"kw-bio\">BU</span> → recherche de colique néphrétique / dilatation</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">TDM</span> abdomino-pelvien</strong></td>\n            <td>Si doute entre <strong>IGH et appendicite</strong>, ou recherche d’une complication (<span class=\"kw-clinique\">abcès</span>)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">IRM</span> pelvienne</strong></td>\n            <td>Doutes diagnostiques persistants · <strong>femme enceinte</strong> (pas d’<span class=\"kw-clinique\">irradiation</span>)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">Cœlioscopie</span></strong><br><em>(diagnostique + thérapeutique)</em></td>\n            <td>Si doute diagnostique persistant ou indication chirurgicale (torsion, GEU, ATO)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> <em>Pas d’imagerie systématique dans le syndrome douloureux vésical chronique</em> (déplacé dans l’onglet « Astuces PU &amp; Pièges ») — l’examen de référence est la <strong><span class=\"kw-imagerie\">cystoscopie</span></strong>, pas l’écho ni le <span class=\"kw-imagerie\">scanner</span>.\n      </div>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong>Évaluation hémodynamique <span class=\"q\">— 1er réflexe systématique</span></strong></p><ul><li><span class=\"kw-alerte\">Instabilité hémodynamique</span> (<span class=\"kw-clinique\">tachycardie</span> précédant la <span class=\"kw-clinique\">chute de PA</span>) évoque un <span class=\"kw-def\">hémopéritoine</span> — rechercher en <span class=\"kw-alerte\">urgence</span></li><li>Si état clinique le permet → <span class=\"kw-imagerie\">échographie pelvienne</span> confirmant l'<span class=\"kw-def\">hémopéritoine</span></li><li>Si instabilité majeure → <span class=\"kw-ttt\">chirurgie en urgence directe</span> (pas d'attente de l'imagerie)</li></ul><p><strong>Hémopéritoine massif <span class=\"q\">— <span class=\"kw-alerte\">rupture</span> tubaire GEU ou hémorragie de kyste</span></strong></p><p><span class=\"kw-ttt\">Cœlioscopie</span> hémostase en <span class=\"kw-alerte\">urgence</span> (<span class=\"kw-ttt\">salpingectomie</span> ou <span class=\"kw-ttt\">salpingotomie</span> selon contexte)</p><ul><li><span class=\"kw-alerte\">Pronostic vital</span> engagé immédiatement</li><li><span class=\"kw-bio\">β-hCG</span> positif → <span class=\"kw-alerte\">rupture</span> de <span class=\"kw-def\">GEU</span> jusqu'à preuve du contraire</li></ul><p><strong>Torsion d'annexe <span class=\"q\">— <span class=\"kw-alerte\">urgence</span> vasculaire ovarienne</span></strong></p><p><span class=\"kw-ttt\">Cœlioscopie</span> de détorsion en <span class=\"kw-chiffre\">&lt; 6–8 h</span> (conservation ovarienne si possible)</p><ul><li>Risque de <span class=\"kw-alerte\">nécrose ovarienne</span> irréversible au-delà de <span class=\"kw-chiffre\">6–8 h</span></li><li>Douleur <span class=\"kw-clinique\">brutale</span>, très intense, résistant aux <span class=\"kw-ttt\">antalgiques</span> de palier III</li></ul>","hospit":"<p><strong>Circuit chirurgical immédiat :</strong> <span class=\"kw-alerte\">instabilité hémodynamique</span> ou <span class=\"kw-alerte\">hémopéritoine</span> confirmé → bloc opératoire sans délai.<br><strong>Médical ambulatoire :</strong> <span class=\"kw-def\">IGH</span> simple (<span class=\"kw-clinique\">apyrexie</span>, absence de <span class=\"kw-alerte\">défense</span>, pas d'<span class=\"kw-def\">ATO</span>) → <span class=\"kw-ttt\">antibiothérapie</span> orale en ambulatoire.<br><strong><span class=\"kw-alerte\">Hospitalisation</span> médicale :</strong> <span class=\"kw-def\">IGH</span> compliquée (<span class=\"kw-def\">ATO</span>, <span class=\"kw-clinique\">fièvre</span> élevée, <span class=\"kw-alerte\">irritation péritonéale</span>) → <span class=\"kw-ttt\">antibiothérapie</span> <span class=\"kw-ttt\">IV</span> + <span class=\"kw-def\">surveillance</span>.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Instabilité hémodynamique</span> : <span class=\"kw-clinique\">tachycardie</span> &gt;<span class=\"kw-chiffre\"> 100 bpm</span> et/ou <span class=\"kw-clinique\">PA systolique</span> &lt; <span class=\"kw-chiffre\">90 mmHg</span></li><li><span class=\"kw-bio\">β-hCG</span> positif avec <span class=\"kw-alerte\">défense abdominale</span> ou <span class=\"kw-alerte\">contracture</span> → <span class=\"kw-def\">rupture de GEU</span> avec hémopéritoine</li><li><span class=\"kw-clinique\">Scapulalgie</span> (<span class=\"kw-clinique\">irradiation</span> en épaule) → <span class=\"kw-alerte\">épanchement intrapéritonéal</span> compressif</li><li><span class=\"kw-alerte\">Irritation péritonéale</span> généralisée : <span class=\"kw-clinique\">défense diffuse</span> ou <span class=\"kw-clinique\">contracture</span> → torsion compliquée, pelvipéritonite</li><li><span class=\"kw-alerte\">Anémie aiguë</span> clinique (pâleur, <span class=\"kw-clinique\">lipothymie</span>) → saignement actif intrapéritonéal</li></ul>"},"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Douleur pelvienne aiguë — Bilan initial : PA · pouls · β-hCG systématique (femme en âge de procréer)","detail":"<h4>CAT — douleur pelvienne aiguë chez la femme — Triage initial : β-hCG d'abord, puis hémodynamique, puis orientation étiologique</h4>","branches":[{"to":"q-hcg-pos","label":"β-hCG positif","color":"red"},{"to":"q-hcg-neg","label":"β-hCG négatif","color":"blue"}]},{"id":"q-hcg-pos","kind":"decision","label":"Instabilité hémodynamique ? — <span class=\"kw-clinique\">Tachycardie</span> <span class=\"kw-chiffre\">> 100 bpm</span> et/ou PA syst < <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>90</span> mmHg</span> · pâleur · <span class=\"kw-clinique\">lipothymie</span>","branches":[{"to":"t-geu-choc","label":"Oui — hémopéritoine clinique","color":"red"},{"to":"q-hcg-stable","label":"Non — patiente stable","color":"amber"}]},{"id":"t-geu-choc","kind":"terminal","label":"GEU rompue — hémopéritoine massif","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-alerte\">Choc hémorragique</span> : <span class=\"kw-clinique\">tachycardie</span>, <span class=\"kw-clinique\">hypotension</span>, <span class=\"kw-clinique\">pâleur</span></li><li><span class=\"kw-clinique\">Scapulalgie</span> possible (épanchement comprimant le diaphragme)</li><li><span class=\"kw-alerte\">Défense abdominale</span> ou <span class=\"kw-alerte\">contracture</span></li></ul><h4>CAT</h4><ul><li><span class=\"kw-ttt\">Voie veineuse</span> + remplissage + <span class=\"kw-bio\">groupe-Rh-RAI</span> immédiat</li><li><span class=\"kw-ttt\">Chirurgie en urgence directe</span> sans attendre l'imagerie</li><li><span class=\"kw-ttt\">Cœlioscopie</span> (<span class=\"kw-ttt\">salpingectomie</span> ou <span class=\"kw-ttt\">salpingotomie</span> selon contexte)</li></ul><h4>Renvoi</h4><ul><li>Item 25 (<span class=\"kw-ci\">Grossesse</span> extra-utérine)</li></ul>"},{"id":"q-hcg-stable","kind":"decision","label":"Localisation échographique de la grossesse ? — Échographie pelvienne en urgence : vacuité utérine ? masse latéro-utérine ? hématosalpinx ?","branches":[{"to":"t-geu-stable","label":"Vacuité utérine + masse annexielle / hématosalpinx","color":"red"},{"to":"t-corps-jaune","label":"Sac intrautérin visible — complication du corps jaune","color":"amber"}]},{"id":"t-geu-stable","kind":"terminal","label":"GEU — patiente stable","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Douleur</span> en fosse iliaque unilatérale</li><li><span class=\"kw-clinique\">Métrorragies sépia</span> peu abondantes</li><li><span class=\"kw-imagerie\">Masse latéro-utérine</span> douloureuse au <span class=\"kw-alerte\">TV</span></li></ul><h4>CAT</h4><ul><li>Avis chirurgical immédiat même si stable</li><li><span class=\"kw-ttt\">Méthotrexate</span> IM si critères stricts (hCG &lt; <span class=\"kw-chiffre\">5 000 UI/L</span>, <span class=\"kw-clinique\">masse</span> &lt; <span class=\"kw-chiffre\">3 cm</span>, pas d'activité cardiaque)</li><li><span class=\"kw-ttt\">Cœlioscopie</span> chirurgicale dans les autres cas</li></ul><h4>Renvoi</h4><ul><li>Item 25 (<span class=\"kw-ci\">Grossesse</span> extra-utérine)</li></ul>"},{"id":"t-corps-jaune","kind":"terminal","label":"Complication du corps jaune gestationnel","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-ci\">Grossesse</span> intrautérine confirmée</li><li><span class=\"kw-clinique\">Douleur</span> pelvienne unilatérale ± <span class=\"kw-clinique\">épanchement pelvien</span> à l'écho</li></ul><h4>CAT</h4><ul><li><span class=\"kw-def\">Surveillance</span> clinique et échographique</li><li><span class=\"kw-ttt\">Antalgiques</span> simples (<span class=\"kw-ttt\">paracétamol</span>)</li><li><span class=\"kw-ttt\">Chirurgie</span> si <span class=\"kw-alerte\">hémorragie active</span> sur kyste du corps jaune rompu</li></ul><h4>Renvoi</h4><ul><li>Item 43 (Hémorragie génitale chez la femme)</li></ul>"},{"id":"q-hcg-neg","kind":"decision","label":"Instabilité hémodynamique ? — Chute de PA · tachycardie · signes d'anémie aiguë","branches":[{"to":"t-hemo-kyste","label":"Oui — hémopéritoine non gravidique","color":"red"},{"to":"q-orientation","label":"Non — patiente stable","color":"blue"}]},{"id":"t-hemo-kyste","kind":"terminal","label":"Rupture hémorragique de kyste ovarien","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Douleur</span> pelvienne brutale unilatérale</li><li><span class=\"kw-alerte\">Instabilité hémodynamique</span> + <span class=\"kw-alerte\">hémopéritoine</span> à l'écho</li><li><span class=\"kw-bio\">β-hCG</span> négatif (élimine la GEU)</li></ul><h4>CAT</h4><ul><li><span class=\"kw-ttt\">Cœlioscopie</span> hémostase en <span class=\"kw-alerte\">urgence</span></li><li><span class=\"kw-ttt\">Kystectomie</span> ou <span class=\"kw-ttt\">annexectomie</span> selon l'aspect</li></ul><h4>Renvoi</h4><ul><li>Item 44 (<span class=\"kw-clinique\">Tuméfaction</span> pelvienne chez la femme)</li></ul>"},{"id":"q-orientation","kind":"decision","label":"Orientation clinique principale ? — Mode de début · topographie · fièvre · signes annexes","branches":[{"to":"t-torsion","label":"Début brutal — douleur très intense résistant aux antalgiques — masse annexielle","color":"red"},{"to":"q-igh","label":"Début progressif — fièvre — leucorrhées — douleur à la mobilisation utérine","color":"amber"},{"to":"t-appendicite","label":"Douleur en FID — fièvre modérée — signes digestifs","color":"blue"},{"to":"t-kyste-hemorragique","label":"Début brutal — kyste connu — pas de fièvre — douleur modérée courte","color":"amber"}]},{"id":"t-torsion","kind":"terminal","label":"Torsion d'annexe","color":"red","detail":"<h4>Clinique</h4><ul><li>Douleur <span class=\"kw-clinique\">brutale « coup de tonnerre »</span>, très intense, <span class=\"kw-clinique\">irradiation</span> lombaire possible</li><li><span class=\"kw-clinique\">Nausées/vomissements</span> d'origine vagale fréquents</li><li><span class=\"kw-imagerie\">Arrêt des flux Doppler</span> au pédicule annexiel (signe évocateur mais non constant)</li><li>Notion de <span class=\"kw-etio\">kyste ovarien</span> connu</li></ul><h4>CAT</h4><ul><li><span class=\"kw-ttt\">Cœlioscopie</span> de détorsion en <span class=\"kw-chiffre\">&lt; 6–8 h</span></li><li>Conservation ovarienne recherchée même si ovaire noir (vascularisation souvent récupérable)</li><li><span class=\"kw-ttt\">Kystectomie</span> associée si kyste présent</li></ul><h4>Renvoi</h4><ul><li>Item 44 (<span class=\"kw-clinique\">Tuméfaction</span> pelvienne chez la femme)</li></ul>"},{"id":"q-igh","kind":"decision","label":"IGH — forme simple ou compliquée ? — Rechercher ATO à l'écho · CRP · défense abdominale","branches":[{"to":"t-igh-comp","label":"ATO ou pelvipéritonite — défense — CRP très élevée","color":"red"},{"to":"t-igh-simple","label":"IGH simple — apyrexie relative — pas d'ATO","color":"amber"}]},{"id":"t-igh-comp","kind":"terminal","label":"IGH compliquée (ATO / pelvipéritonite)","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-alerte\">Défense abdominale</span> ou <span class=\"kw-alerte\">contracture</span></li><li><span class=\"kw-clinique\">Fièvre</span> élevée + <span class=\"kw-bio\">CRP</span> très élevée + <span class=\"kw-bio\">hyperleucocytose</span></li><li><span class=\"kw-imagerie\">Masse hétérogène liquidienne</span> annexielle à l'écho (<span class=\"kw-def\">ATO</span>)</li><li><span class=\"kw-clinique\">Ténesme rectal</span> si ATO dans le cul-de-sac de Douglas</li></ul><h4>CAT</h4><ul><li><span class=\"kw-alerte\">Hospitalisation</span> + <span class=\"kw-ttt\">antibiothérapie IV</span> probabiliste bispécifique</li><li><span class=\"kw-ttt\">Drainage chirurgical</span> (cœlioscopie) si ATO &gt; <span class=\"kw-chiffre\">8 cm</span> ou absence de réponse à <span class=\"kw-chiffre\">72 h</span></li><li>Ablation du <span class=\"kw-ttt\">DIU</span> si en place</li><li><span class=\"kw-bio\">Prélèvements</span> vaginaux et endocervicaux + bilan IST</li></ul>"},{"id":"t-igh-simple","kind":"terminal","label":"IGH simple (salpingite / endométrite)","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Douleur</span> pelvienne diffuse à prédominance bilatérale</li><li><span class=\"kw-clinique\">Leucorrhées</span> odorantes ± <span class=\"kw-clinique\">métrorragies</span></li><li>Douleur à la <span class=\"kw-clinique\">mobilisation utérine</span> et à la <span class=\"kw-clinique\">palpation annexielle</span></li><li><span class=\"kw-bio\">Hyperleucocytose</span> fréquemment absente dans les formes simples</li></ul><h4>CAT</h4><ul><li><span class=\"kw-ttt\">Antibiothérapie probabiliste orale</span> (céphalosporine + <span class=\"kw-ttt\">métronidazole</span> ± <span class=\"kw-ttt\">doxycycline</span>)</li><li><span class=\"kw-bio\">Prélèvements</span> vaginaux et endocervicaux avant ATB</li><li>Ablation du <span class=\"kw-ttt\">DIU</span> si en place</li><li>Bilan partenaire + <span class=\"kw-bio\">sérologie IST</span></li><li><span class=\"kw-def\">Réévaluation</span> à <span class=\"kw-chiffre\">72 h</span></li></ul>"},{"id":"t-appendicite","kind":"terminal","label":"Appendicite aiguë (cause non gynécologique)","color":"blue","detail":"<h4>Clinique</h4><ul><li>Douleur débutant en <span class=\"kw-clinique\">épigastre</span> puis migrant en <span class=\"kw-clinique\">FID</span></li><li><span class=\"kw-clinique\">Signe de Rovsing</span> (douleur FID à la compression FIG) · <span class=\"kw-clinique\">signe de Blumberg</span> (douleur FID à la décompression FIG) · <span class=\"kw-clinique\">psoïtis</span></li><li><span class=\"kw-bio\">Hyperleucocytose quasi-constante</span> (différence avec IGH simple)</li></ul><h4>Imagerie</h4><ul><li><span class=\"kw-imagerie\">Échographie</span> : appendice &gt; <span class=\"kw-chiffre\">6 mm</span>, incompressible, paroi &gt; <span class=\"kw-chiffre\">3 mm</span></li><li><span class=\"kw-imagerie\">TDM abdomino-pelvien</span> si doute écho ou suspicion de forme compliquée</li></ul><h4>CAT</h4><ul><li><span class=\"kw-ttt\">Appendicectomie</span> cœlioscopique en <span class=\"kw-alerte\">urgence</span> · avis chirurgical immédiat</li></ul>"},{"id":"t-kyste-hemorragique","kind":"terminal","label":"Hémorragie intrakystique / rupture de kyste (patiente stable)","color":"amber","detail":"<h4>Clinique</h4><ul><li>Douleur <span class=\"kw-clinique\">unilatérale</span>, d'<span class=\"kw-clinique\">évolution</span> brève</li><li><span class=\"kw-imagerie\">Épanchement pelvien</span> de faible abondance à l'écho</li><li>Pas de <span class=\"kw-clinique\">fièvre</span>, <span class=\"kw-bio\">β-hCG</span> négatif, pas d'instabilité hémodynamique</li></ul><h4>CAT</h4><ul><li><span class=\"kw-def\">Surveillance</span> clinique et <span class=\"kw-ttt\">biologique</span> (<span class=\"kw-bio\">NFS</span>)</li><li><span class=\"kw-ttt\">Antalgiques</span> (<span class=\"kw-ttt\">paracétamol</span> ± <span class=\"kw-ttt\">AINS</span> si hémorragie exclue)</li><li>Contrôle <span class=\"kw-imagerie\">échographique</span> à distance</li><li><span class=\"kw-ttt\">Chirurgie</span> si douleurs persistantes ou saignement progressif</li></ul><h4>Renvoi</h4><ul><li>Item 44 (<span class=\"kw-clinique\">Tuméfaction</span> pelvienne chez la femme)</li></ul>"}]},"cards":[{"i":"8767fb7d18ac","n":40,"o":"40-1","u":"Définition","t":"Connaître la définition de la douleur pelvienne aiguë (DPA) et chronique (DPC)","q":"Comment définit-on une douleur pelvienne aiguë (DPA) chez la femme ?","a":"<p>Une douleur pelvienne aiguë (DPA) correspond à une douleur pelvienne de <strong>moins de 1 mois</strong> d'évolution. Elle se caractérise par un <strong>début récent et rapide</strong>.</p>"},{"i":"c86add6004f7","n":40,"o":"40-1","u":"Définition","t":"Connaître la définition de la douleur pelvienne aiguë (DPA) et chronique (DPC)","q":"Comment définit-on une douleur pelvienne chronique (DPC) chez la femme ?","a":"<p>Une douleur pelvienne chronique (DPC) est une douleur pelvienne qui dure depuis <strong>plus de 6 mois</strong>. Elle peut être <strong>permanente ou intermittente</strong>, et cyclique ou non.</p>"},{"i":"f08839bba2bd","n":40,"o":"40-1","u":"Définition","t":"Connaître la définition de la douleur pelvienne aiguë (DPA) et chronique (DPC)","q":"Quelle est la définition générale des algies pelviennes chez la femme ?","a":"<p>Les algies pelviennes regroupent l'ensemble des symptômes douloureux, spontanés ou provoqués, siégeant dans la région de l'<strong>hypogastre</strong> et/ou des <strong>fosses iliaques droite et gauche</strong>.</p>"},{"i":"068157375fb2","n":40,"o":"40-2","u":"Étiologies","t":"Connaître les étiologies des DPA","q":"Quelles sont les étiologies des douleurs pelviennes aiguës (DPA) en lien avec la grossesse ou le post-partum ?","a":"Les étiologies des DPA en lien avec la grossesse ou le post-partum incluent :\n<ul>\n<li>La <strong>grossesse extra-utérine (GEU)</strong>.</li>\n<li>La <strong>fausse couche spontanée</strong>.</li>\n<li>La <strong>rétention post-fausse couche</strong>.</li>\n<li>L'<strong>endométrite du post-partum ou post-abortum</strong>.</li>\n<li>Les <strong>complications du corps jaune gestationnel</strong> (hémorragique, kyste et ses complications).</li>\n</ul>"},{"i":"14de6cae27d6","n":40,"o":"40-2","u":"Étiologies","t":"Connaître les étiologies des DPA","q":"Quelles sont les causes urologiques des douleurs pelviennes aiguës (DPA) ?","a":"Les causes urologiques des DPA sont :\n<ul>\n<li>La <strong>colique néphrétique</strong>.</li>\n<li>La <strong>pyélonéphrite aiguë (PNA)</strong>.</li>\n<li>Les <strong>infections urinaires (IU) basses</strong>.</li>\n</ul>"},{"i":"98e281be9b54","n":40,"o":"40-2","u":"Étiologies","t":"Connaître les étiologies des DPA","q":"Quelles sont les étiologies annexielles des douleurs pelviennes aiguës (DPA) ?","a":"Les étiologies annexielles des DPA sont :\n<ul>\n<li>La <strong>torsion d’annexe</strong>.</li>\n<li>Les <strong>complications de kyste ovarien</strong> (hémorragie intra-kystique, rupture, torsion).</li>\n<li>La <strong>dysovulation</strong>.</li>\n</ul>"},{"i":"cab2ecf39e18","n":40,"o":"40-2","u":"Étiologies","t":"Connaître les étiologies des DPA","q":"Quelles sont quelques étiologies rares de douleurs pelviennes aiguës (DPA) ?","a":"Parmi les étiologies rares de DPA, on retrouve :\n<ul>\n<li>La <strong>sacro-iléite bactérienne</strong>.</li>\n<li>L'<strong>ostéite pelvienne</strong>.</li>\n<li>L'<strong>anévrisme de l’artère iliaque</strong>.</li>\n<li>L'<strong>infection d’un kyste de l’ouraque</strong>.</li>\n</ul>"},{"i":"cbdcede11b67","n":40,"o":"40-2","u":"Étiologies","t":"Connaître les étiologies des DPA","q":"Quelles sont les causes infectieuses des douleurs pelviennes aiguës (DPA) ?","a":"Les causes infectieuses des DPA sont :\n<ul>\n<li>Les <strong>Infections Génitales Hautes (IGH)</strong> telles que salpingite, endométrite, pelvipéritonite, abcès tubo-ovarien.</li>\n<li>L'<strong>appendicite aiguë</strong>.</li>\n<li>La <strong>pyélonéphrite aiguë (PNA)</strong>.</li>\n<li>Les <strong>infections urinaires (IU) basses</strong>.</li>\n</ul>"},{"i":"d7f893b23bb5","n":40,"o":"40-2","u":"Étiologies","t":"Connaître les étiologies des DPA","q":"Quelles sont les étiologies des douleurs pelviennes aiguës (DPA) en cas de présence d'un fibrome utérin ?","a":"En présence d'un fibrome utérin, les étiologies des DPA peuvent être :\n<ul>\n<li>La <strong>nécrobiose aiguë</strong> du fibrome.</li>\n<li>La <strong>torsion d’un myome sous-séreux pédiculé</strong>.</li>\n<li>L'<strong>accouchement d’un myome sous-muqueux</strong> par le col utérin.</li>\n</ul>"},{"i":"79c52de61ba6","n":40,"o":"40-4","u":"Diagnostic positif","t":"Connaitre les élements de l’interrogatoire et de l’examen clinique utiles au diagnostic des DPA","q":"Quelle est la triade d'examens complémentaires de première ligne à réaliser chez toute femme en âge de procréer présentant une douleur pelvienne aiguë ?","a":"<p>Chez toute femme en âge de procréer avec une douleur pelvienne aiguë, la triade d'examens de première ligne à réaliser pour éliminer les 4 urgences est :</p><ul><li>Dosage plasmatique des <strong>β-hCG</strong>.</li><li><strong>Bandelette Urinaire (BU)</strong>.</li><li><strong>Échographie pelvienne</strong>.</li></ul>"},{"i":"cc01d7e75d8d","n":40,"o":"40-4","u":"Diagnostic positif","t":"Connaitre les élements de l’interrogatoire et de l’examen clinique utiles au diagnostic des DPA","q":"Quels sont les éléments à rechercher lors de l'examen clinique d'une patiente présentant des douleurs pelviennes ?","a":"<p>L'examen clinique doit comporter :</p><ul><li>L'<strong>inspection et palpation abdominale</strong> : recherche de défense, contracture, masse.</li><li>L'examen au <strong>spéculum</strong> : recherche de leucorrhées, métrorragies, évaluation de l'aspect du col.</li><li>Le <strong>toucher vaginal (TV)</strong> :</li><ul><li>Recherche de <strong>douleur à la mobilisation utérine</strong> (orientant vers une Infection Génitale Haute - IGH).</li><li>Recherche de <strong>masse latéro-utérine</strong> (orientant vers une Grossesse Extra-Utérine - GEU ou un kyste compliqué).</li><li>Recherche de <strong>sensibilité du cul-de-sac de Douglas</strong> (orientant vers un hémopéritoine ou une IGH).</li><li>Recherche d'<strong>hypersensibilité de la paroi vaginale antérieure</strong> (orientant vers un syndrome douloureux vésical).</li></ul><li>Une <strong>Bandelette Urinaire (BU) systématique</strong> : recherche de nitrites, leucocytes, hématurie.</li></ul>"},{"i":"d944f6c9c16f","n":40,"o":"40-4","u":"Diagnostic positif","t":"Connaitre les élements de l’interrogatoire et de l’examen clinique utiles au diagnostic des DPA","q":"Quels sont les éléments clés de l'interrogatoire à recueillir face à une douleur pelvienne chronique chez la femme ?","a":"<p>Face à une douleur pelvienne chronique (évolution &gt; 6 mois), les éléments clés de l'interrogatoire sont :</p><ul><li>L'<strong>évolution</strong> : permanente ou intermittente.</li><li>L'<strong>apparition dans le cycle</strong> : prémenstruel, dysménorrhée, intermenstruel.</li><li>Le <strong>type</strong> : pesanteur, tiraillement, picotement, avec ou sans irradiation.</li><li>Les <strong>signes associés</strong> :</li><ul><li>Céphalées, lombalgies.</li><li>Diarrhées, constipation.</li><li>Métrorragies, dyspareunies.</li><li>Infertilité.</li></ul><li>Les <strong>antécédents</strong> : gynécologiques, obstétricaux, chirurgicaux, contraception orale (CO).</li><li>Le <strong>retentissement sur la qualité de vie</strong>.</li></ul>"},{"i":"fa1d45b26858","n":40,"o":"40-4","u":"Diagnostic positif","t":"Connaitre les élements de l’interrogatoire et de l’examen clinique utiles au diagnostic des DPA","q":"Quels sont les éléments clés de l'interrogatoire à recueillir face à une douleur pelvienne aiguë chez la femme ?","a":"<p>Face à une douleur pelvienne aiguë, les éléments clés de l'interrogatoire sont :</p><ul><li>La <strong>date d'apparition</strong> : récente (&lt; 1 mois), subite.</li><li>L'<strong>évolution</strong> : rapide.</li><li>Le <strong>type</strong> : coup de poignard, torsion, colique, avec ou sans irradiation.</li><li>Les <strong>signes associés</strong> :</li><ul><li>Date des dernières règles, signes de grossesse, métrorragies.</li><li>Signes d'infection (mètreurragies purulentes, fièvre, frissons).</li><li>Nausées, vomissements.</li><li>Signes urinaires (SFU).</li><li>Position antalgique.</li></ul><li>Les <strong>antécédents</strong> : gynécologiques, obstétricaux (GOB), chirurgicaux.</li><li>La <strong>contraception</strong> et les <strong>conduites à risque d'IST</strong>.</li></ul>"},{"i":"5c58b05d2e39","n":40,"o":"40-6","u":"Identifier une urgence","t":"Connaître les urgences chirurgicales devant une douleur aiguë pelvienne","q":"Quels sont les éléments clés de l'interrogatoire et de l'examen clinique orientant vers une Rupture hémorragique de kyste ovarien ?","a":"À l'interrogatoire, la patiente rapporte des <strong>douleurs brutales et intenses</strong>, pouvant être associées à une <strong>scapulalgie</strong>. Il est important de rechercher des antécédents de kyste ovarien connu.\nÀ l'examen clinique, on peut observer une <strong>défense abdominale</strong>, voire une contracture. Au toucher vaginal, on retrouve une <strong>douleur diffuse</strong> et un cul-de-sac de Douglas comblé."},{"i":"7867b93b50c3","n":40,"o":"40-6","u":"Identifier une urgence","t":"Connaître les urgences chirurgicales devant une douleur aiguë pelvienne","q":"Quels sont les signes cliniques et paracliniques suggestifs d'une Infection Génitale Haute (IGH) ?","a":"Cliniquement, une IGH se caractérise par :\n<ul>\n<li>Des <strong>douleurs pelviennes modérées d’installation lente</strong> (évocatrice si > 4 jours), pouvant irradier vers la région lombaire ou l'hypocondre droit.</li>\n<li>Un <strong>syndrome infectieux</strong> (fièvre, frissons).</li>\n<li>Des leucorrhées abondantes, épaisses, jaunâtres et/ou purulentes.</li>\n<li>Des métrorragies peuvent survenir.</li>\n<li>À l'examen vaginal : <strong>douleur ++ à la mobilisation utérine et au cul-de-sac de Douglas</strong>, douleur bilatérale à la palpation des annexes.</li>\n</ul>\nParacliniquement :\n<ul>\n<li>La <strong>NFS</strong> montre un syndrome inflammatoire biologique (SIB).</li>\n<li>La <strong>bactériologie</strong> recherche des IST (gonocoque, <i>C. trachomatis</i>, <i>M. genitalium</i>).</li>\n</ul>"},{"i":"7f4b99e59d5c","n":40,"o":"40-6","u":"Identifier une urgence","t":"Connaître les urgences chirurgicales devant une douleur aiguë pelvienne","q":"Quels sont les cinq diagnostics qui doivent être systématiquement évoqués devant toute douleur pelvienne aiguë chez une femme en raison de leur pronostic vital et/ou fonctionnel ?","a":"Les cinq diagnostics à évoquer systématiquement sont :\n<ul>\n<li>La <strong>Grossesse Extra-Utérine (GEU)</strong></li>\n<li>La <strong>Torsion d’annexe</strong></li>\n<li>La <strong>Rupture hémorragique de kyste</strong> (avec hémopéritoine)</li>\n<li>L'<strong>Infection Génitale Haute (IGH)</strong></li>\n<li>L'<strong>Appendicite aiguë</strong></li>\n</ul>"},{"i":"e2ae02109de3","n":40,"o":"40-6","u":"Identifier une urgence","t":"Connaître les urgences chirurgicales devant une douleur aiguë pelvienne","q":"Quels sont les signes d'orientation diagnostique à l'examen clinique et aux examens complémentaires pour une Torsion d'annexe ?","a":"À l'examen clinique, on retrouvera :\n<ul>\n<li>Une <strong>défense abdominale</strong>, éventuellement un météorisme.</li>\n<li>Au toucher vaginal, une <strong>douleur latéro-utérine unilatérale très douloureuse au niveau du collet utérin</strong>.</li>\n</ul>\nAux examens complémentaires, l'<strong>échographie pelvienne</strong> montrera :\n<ul>\n<li>Un <strong>ovaire augmenté de taille</strong>, éventuellement un kyste associé.</li>\n<li>Des <strong>anomalies de vascularisation</strong> avec, de manière caractéristique, une disparition du pédicule ovarien au Doppler.</li>\n</ul>"},{"i":"f0a285684df2","n":40,"o":"40-6","u":"Identifier une urgence","t":"Connaître les urgences chirurgicales devant une douleur aiguë pelvienne","q":"Quelle est la définition clinique de la Grossesse Extra-Utérine (GEU) et ses signes clés à l'interrogatoire ?","a":"La GEU est une <strong>nidation embryonnaire en dehors de la cavité utérine</strong>. Cliniquement, elle se manifeste par l'association de :\n<ul>\n<li><strong>Douleurs pelviennes aiguës</strong></li>\n<li><strong>Métrorragies « sépia »</strong></li>\n<li>Un <strong>retard de règles</strong></li>\n<li>Des signes sympathiques de grossesse (nausées, tension mammaire) peuvent également être présents.</li>\n</ul>"},{"i":"f2f74910e5c4","n":40,"o":"40-6","u":"Identifier une urgence","t":"Connaître les urgences chirurgicales devant une douleur aiguë pelvienne","q":"Quel est le piège classique à connaître devant toute douleur pelvienne aiguë chez une femme en âge de procréer ?","a":"Le piège classique est de ne pas réaliser un dosage sanguin de <strong>β-hCG en urgence</strong>. Il est impératif de le faire quel que soit le contexte contraceptif allégué, car l'absence de β-hCG peut faire manquer un diagnostic crucial, notamment une Grossesse Extra-Utérine (GEU)."},{"i":"3d3f76e38e6c","n":40,"o":"40-7","u":"Définition","t":"Savoir distinguer les douleurs chroniques des douleurs aiguës","q":"Quel piège diagnostique important doit-on avoir à l'esprit concernant les douleurs pelviennes chroniques (DPC) ?","a":"<p>Une DPC peut se <strong>décompenser en phase aiguë</strong> (par exemple, une poussée d'endométriose ou une torsion sur kyste ovarien connu). Il est crucial de se rappeler qu'un terrain chronique <strong>n'élimine jamais une urgence surajoutée</strong>.</p>"},{"i":"459a8305e327","n":40,"o":"40-7","u":"Définition","t":"Savoir distinguer les douleurs chroniques des douleurs aiguës","q":"Comment définit-on une douleur pelvienne aiguë (DPA) chez la femme ?","a":"<p>Une douleur pelvienne aiguë (DPA) se caractérise par une durée d'évolution <strong>inférieure à 1 mois</strong>. Son installation est subite et récente, avec une évolution rapide. Le type de douleur est souvent décrit comme un coup de poignard, une torsion ou une colique.</p>"},{"i":"a0da084dda25","n":40,"o":"40-7","u":"Définition","t":"Savoir distinguer les douleurs chroniques des douleurs aiguës","q":"Comment définit-on une douleur pelvienne chronique (DPC) chez la femme ?","a":"<p>Une douleur pelvienne chronique (DPC) est caractérisée par une durée d'évolution <strong>supérieure à 6 mois</strong>. Son installation est progressive et ancienne, pouvant être cyclique ou non, permanente ou intermittente. Le type de douleur est souvent une pesanteur, un tiraillement ou un picotement.</p>"},{"i":"c4cd953db6ba","n":40,"o":"40-7","u":"Définition","t":"Savoir distinguer les douleurs chroniques des douleurs aiguës","q":"Quels sont les enjeux principaux et les causes dominantes à considérer face à une douleur pelvienne aiguë (DPA) et une douleur pelvienne chronique (DPC) ?","a":"<ul><li>Pour une <strong>DPA</strong>, l'enjeu primordial est d'<strong>éliminer une urgence vitale</strong> (par exemple, une grossesse extra-utérine, une torsion d'annexe, une infection génitale haute, une appendicite). Les causes dominantes sont principalement gynécologiques, obstétricales ou chirurgicales aiguës.</li><li>Pour une <strong>DPC</strong>, l'enjeu principal est le <strong>retentissement sur la qualité de vie</strong> de la patiente, avec une errance diagnostique fréquente. Les causes dominantes sont plus souvent digestives, puis urinaires, et enfin gynécologiques.</li></ul>"},{"i":"43bcf283101a","n":40,"o":"40-8","u":"Définition","t":"Connaître les principales étiologies des DPC","q":"Quelle est la définition des Douleurs Pelviennes Chroniques (DPC) chez la femme ?","a":"<p>Les Douleurs Pelviennes Chroniques (DPC) correspondent à des douleurs de la région pelvienne qui évoluent depuis <strong>plus de 6 mois</strong>.</p>"},{"i":"53f1f1573dbf","n":40,"o":"40-8","u":"Définition","t":"Connaître les principales étiologies des DPC","q":"Quelles sont les causes des douleurs pelviennes chroniques cycliques intermenstruelles et des dysménorrhées ?","a":"<ul><li><strong>Syndrome intermenstruel :</strong> douleur contemporaine de la période ovulatoire, peu intense, quelques jours en milieu de cycle, éventuellement associée à des métrorragies. L'examen est rassurant sans nécessité d'examens paracliniques, et les antalgiques simples sont suffisants.</li><li><strong>Dysménorrhées :</strong> douleurs contemporaines des règles. Elles peuvent être :<ul><li><strong>Organiques (secondaires) :</strong> endométriose, sténoses cervicales (congénitales ou acquises), anomalies utéro-vaginales (synéchies, cancer du col, chirurgie cervicale, malformations congénitales).</li><li><strong>Fonctionnelles (primaires) :</strong> prévalence élevée entre 20 et 24 ans, diminuant avec l’âge, majoritairement considérées comme psychogènes (diagnostic d’élimination).</li></ul></li></ul>"},{"i":"94c2023a2dc9","n":40,"o":"40-8","u":"Définition","t":"Connaître les principales étiologies des DPC","q":"Quelles sont les principales étiologies extra-génitales des Douleurs Pelviennes Chroniques non cycliques ?","a":"<ul><li><strong>Digestives :</strong> colite, Maladies Inflammatoires Chroniques de l'Intestin (MICI), endométriose digestive, hémorroïdes, anomalies anorectales.</li><li><strong>Urinaires :</strong> cystalgie à urines claires (présence de signes urinaires avec des urines stériles).</li><li><strong>Rhumatologiques :</strong> pathologies ostéo-articulaires du bassin ou du rachis lombaire, accentuées par certaines positions.</li></ul>"},{"i":"c19261cc5fd2","n":40,"o":"40-8","u":"Définition","t":"Connaître les principales étiologies des DPC","q":"Quelles sont les principales étiologies génitales organiques des Douleurs Pelviennes Chroniques non cycliques ?","a":"<ul><li><strong>Infections génitales chroniques ou subaiguës :</strong> infections vulvo-vaginales, cervicales, endométrite chronique, ou annexite subaiguë.</li><li><strong>Syndrome de Masters et Allen :</strong> trouble de la statique pelvienne par déficit des ligaments utéro-sacrés (souvent post-accouchement traumatique ou macrosome), se manifestant par une pesanteur soulagée en décubitus, aggravée à l’orthostatisme, des dyspareunies profondes et un utérus très mobile au Toucher Vaginal (TV).</li><li><strong>Syndrome de congestion pelvienne :</strong> varices pelviennes ou ovariennes, fréquemment post-grossesse, avec aggravation à la station debout ou lors des rapports.</li><li><strong>Endométriose pelvienne :</strong> pouvant entraîner une rétroversion utérine douloureuse par rétraction.</li></ul>"},{"i":"218929100812","n":40,"o":"40-9","u":"Examens complémentaires","t":"Connaître les indications des examens d’imagerie devant une algie pelvienne chez la femme","q":"Quel est le piège classique concernant l'imagerie dans le syndrome douloureux vésical chronique ?","a":"<p>Il ne faut <strong>pas réaliser d'imagerie systématique</strong> (échographie ou scanner) dans le syndrome douloureux vésical chronique. L'examen de référence dans ce contexte est la <strong>cystoscopie</strong>.</p>"},{"i":"ab5fa7b3df3b","n":40,"o":"40-9","u":"Examens complémentaires","t":"Connaître les indications des examens d’imagerie devant une algie pelvienne chez la femme","q":"Quelle est la place et les modalités de l'échographie pelvienne dans l'exploration d'une algie pelvienne chez la femme ?","a":"<p>L'échographie pelvienne est l'<strong>examen-clé de première intention</strong>. Elle doit être réalisée en urgence si instabilité hémodynamique ou suspicion d'hémopéritoine. Elle comprend une exploration par <strong>voie abdominale et endovaginale</strong> (sauf chez la femme vierge où seule la voie abdominale est utilisée).</p>"},{"i":"b221a3b6cc46","n":40,"o":"40-9","u":"Examens complémentaires","t":"Connaître les indications des examens d’imagerie devant une algie pelvienne chez la femme","q":"Quelles sont les indications de l'échographie des voies urinaires et du TDM abdomino-pelvien en cas d'algie pelvienne chez la femme ?","a":"<ul><li>L'<strong>échographie des voies urinaires</strong> est indiquée si hématurie à la bandelette urinaire, afin de rechercher une <strong>colique néphrétique</strong> ou une dilatation des voies urinaires.</li><li>Le <strong>TDM abdomino-pelvien</strong> est indiqué en cas de doute diagnostique entre une infection génitale haute (IGH) et une appendicite, ou pour la recherche d'une complication comme un abcès.</li></ul>"},{"i":"b2238aab2d1f","n":40,"o":"40-9","u":"Examens complémentaires","t":"Connaître les indications des examens d’imagerie devant une algie pelvienne chez la femme","q":"Quelle est la règle EDN concernant les examens complémentaires à réaliser devant une douleur pelvienne aiguë chez une femme en âge de procréer ?","a":"<p>Devant une douleur pelvienne aiguë chez une femme en âge de procréer, la règle EDN est de réaliser systématiquement :</p><ul><li>un dosage des <strong>β-hCG</strong></li><li>une <strong>bandelette urinaire</strong> (BU)</li><li>une <strong>échographie pelvienne</strong></li></ul>"},{"i":"be5c7a29a187","n":40,"o":"40-9","u":"Examens complémentaires","t":"Connaître les indications des examens d’imagerie devant une algie pelvienne chez la femme","q":"Quels signes échographiques l'échographie pelvienne peut-elle révéler dans le cadre d'une algie pelvienne chez la femme pour une grossesse extra-utérine, une torsion d'annexe ou une infection génitale haute (IGH) ?","a":"<ul><li>En cas de <strong>grossesse extra-utérine (GEU)</strong> : <strong>vacuité utérine</strong>, masse latéro-utérine, épanchement de Douglas.</li><li>En cas de <strong>torsion d'annexe</strong> : ovaire augmenté de taille (± kyste associé), <strong>arrêt des flux au Doppler</strong>.</li><li>En cas d'<strong>infection génitale haute (IGH)</strong> : épaississement de la paroi tubaire, épanchement intra-tubaire, abcès tubo-ovarien.</li></ul>"},{"i":"ff706d8e6683","n":40,"o":"40-9","u":"Examens complémentaires","t":"Connaître les indications des examens d’imagerie devant une algie pelvienne chez la femme","q":"Dans quelles situations l'IRM pelvienne et la cœlioscopie sont-elles indiquées pour une algie pelvienne chez la femme ?","a":"<ul><li>L'<strong>IRM pelvienne</strong> est indiquée en cas de <strong>doutes diagnostiques persistants</strong>, notamment chez la femme enceinte pour éviter l'irradiation.</li><li>La <strong>cœlioscopie</strong> (diagnostique et thérapeutique) est indiquée en cas de doute diagnostique persistant après bilan non invasif, ou s'il existe une indication chirurgicale claire (comme une torsion d'annexe, une GEU ou un abcès tubo-ovarien - ATO).</li></ul>"}]};